"use client"

import { motion } from "motion/react"

import { cn } from "@/lib/utils"

export const BorderBeam = ({
  className,
  colorFrom = "#f59e0b",
  colorTo = "#8b5cf6",
  onDone,
}: {
  className?: string
  colorFrom?: string
  colorTo?: string
  onDone?: () => void
}) => {
  return (
    <div className="pointer-events-none absolute inset-0 rounded-[inherit] border border-transparent">
      <motion.div
        className={cn("absolute aspect-square w-16 bg-gradient-to-l from-(--color-from) via-(--color-to) to-transparent", className)}
        style={{ "--color-from": colorFrom, "--color-to": colorTo, boxShadow: "0 0 8px #f59e0b, 0 0 16px #8b5cf6" } as React.CSSProperties}
        animate={{ offsetDistance: ["0%", "100%"] }}
        transition={{ repeat: Infinity, duration: 6, ease: "linear" }}
      />
    </div>
  )
}
